let ctd = $('Set Current Element').first().json.currentElement;
let bestMatch = $('Get Best Match').first().json;
let staticData = $('When Executed by Another Workflow').first().json.static_data;

function toFireflyDate(date) {
    return `${date}T00:00:00+01:00`;
}

function isWithdrawal() {
  return ctd.type === 'withdrawal';
}

let foreign_data = {};
if(ctd.foreign_amount)
  foreign_data.foreign_amount = ctd.foreign_amount;
if(ctd.foreign_currency_code)
  foreign_data.foreign_currency_code = ctd.foreign_currency_code;

let budget_data = {};
if(bestMatch.budget)
  budget_data.budget_name = bestMatch.budget;

let category_data = {};
if(bestMatch.category)
  category_data.category_name = bestMatch.category;

let tag_data = {};
if(bestMatch.tags && bestMatch.tags.length > 0)
  tag_data.tags = bestMatch.tags;

// ----------------- set transaction flow info ------------
let tfi = {};
if(isWithdrawal()){
  tfi.source_id = staticData[ctd.account];
  tfi.destination_name = bestMatch.merchant;
}
else{
  tfi.destination_id = staticData[ctd.account];
  tfi.source_name = bestMatch.merchant;
}
// --------------------------------------------------------

let transaction = {
  "error_if_duplicate_hash": false,
  "apply_rules": true,
  "fire_webhooks": false,
  "group_title": null,
  "transactions": [
    {
      "type": ctd.type,
      "date": toFireflyDate(ctd.date),
      "amount": ctd.amount,
      "description": ctd.description,
      "order": 0,
      "currency_code": ctd.currency_code,
      ...foreign_data,
      ...budget_data,
      ...category_data,
      ...tfi,
      "reconciled": true,
      //"piggy_bank_id": 0,
      //"piggy_bank_name": "string",
      //"bill_id": "112",
      //"bill_name": "Monthly rent",
      ...tag_data,
      "notes": ctd.notes,
      "internal_reference": "string",
      "external_id": ctd.id,
      //"external_url": "string",
      //"sepa_cc": "string",
      //"sepa_ct_op": "string",
      //"sepa_ct_id": "string",
      //"sepa_db": "string",
      //"sepa_country": "string",
      //"sepa_ep": "string",
      //"sepa_ci": "string",
      //"sepa_batch_id": "string",
      //"interest_date": "2026-06-21T08:18:46.199Z",
      "book_date": toFireflyDate(ctd.book_date),
      "process_date": toFireflyDate(ctd.date),
      //"due_date": "2026-06-21T08:18:46.199Z",
      "payment_date": toFireflyDate(ctd.payment_date),
      //"invoice_date": "2026-06-21T08:18:46.199Z"
    }
  ]
};

return [{json:{transaction}}]

let transaction = $('Prepare Transaction').first().json.transaction;

transaction.transactions[0].budget_id = $input.first().json.id;
delete transaction.transactions[0].budget_name;
return [{json:{
  transaction
}}]

let transaction = $('If Category Exists').first().json.transaction;
transaction.transactions[0].category_id = $input.first().json.id;
delete transaction.transactions[0].category_name;

return [{json:{
